import assert from 'node:assert/strict'
import fs from 'node:fs'
import os from 'node:os'
import path from 'node:path'

import * as projen from 'projen'
import { CargoPackage, CargoWorkspace } from 'projen-cargo'

const outdir = fs.mkdtempSync(path.join(os.tmpdir(), 'smoke-'))
const project = new projen.Project({ name: 'smoke', outdir })
const read = (file) => fs.readFileSync(path.join(outdir, file), 'utf8')

new CargoWorkspace(project)
new CargoPackage(
  new projen.Project({ name: 'crate', parent: project, outdir: 'crate' }),
)

project.synth()

assert.ok(read('rust-toolchain.toml').includes('channel = "stable"'))
assert.ok(read('crate/Cargo.toml').includes('[package]'))
